describe('Auth Config', () => {
  const originalEnv = process.env;

  beforeEach(() => {
    jest.resetModules(); // Clears the cache
    process.env = { ...originalEnv }; // Restore original env variables
  });

  afterAll(() => {
    process.env = originalEnv; // Restore original env at the end
  });

